"""Apply metadata-only instrumentation to upstream llama.cpp b11840."""
import hashlib,pathlib,sys
BASE_SHA256 = 'dff696ee775fcf0cba56a2c7d99e73c3a7d955011730b43896797b16d8aa824c'
BLOCK = '\n            // Metadata only: bridge native task timing to the returned completion ID.\n            auto safe_id = [](const std::string & value) {\n                return !value.empty() && value.size() <= 200 &&\n                    value.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.:-") == std::string::npos;\n            };\n            auto header = [&req](const std::string & name) {\n                for (const auto & item : req.headers) {\n                    auto key = item.first;\n                    for (auto & ch : key) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));\n                    if (key == name) return item.second;\n                }\n                return std::string();\n            };\n            json identity = {{"task", task.id}, {"completion_id", completion_id}};\n            auto source = header("x-lmc-origin");\n            auto sid = header("x-lmc-session-id");\n            auto tid = header("x-lmc-task-id");\n            auto host = header("x-lmc-host");\n            if (source.empty() && header("user-agent").find("deepseek-harness/") != std::string::npos) {\n                const auto original = json::parse(req.body);\n                if (original.is_object() && original.contains("prompt_cache_key") && original["prompt_cache_key"].is_string()) {\n                    sid = original["prompt_cache_key"].get<std::string>();\n                }\n                if (sid.empty()) sid = header("session_id");\n                source = "DSH"; tid = sid;\n            }\n            if ((source == "Hermes" || source == "DSH") && safe_id(sid) && safe_id(tid)) {\n                identity["origin"] = source; identity["session_id"] = sid; identity["task_id"] = tid;\n                if (safe_id(host)) identity["host"] = host;\n            }\n            SRV_INF("LMC_REQUEST %s\\n", identity.dump().c_str());\n'
p=pathlib.Path(sys.argv[1])/'tools/server/server-context.cpp'
s=p.read_text()
if 'LMC_REQUEST %s' in s:raise SystemExit('Instrumentation already present')
if hashlib.sha256(s.encode()).hexdigest()!=BASE_SHA256:raise SystemExit('Source differs from pinned b11840; refusing patch')
needle='            task.params.oaicompat_model   = meta->model_name;'
p.write_text(s.replace(needle,needle+BLOCK,1))
